import Foundation

/// ZIP32 store-method archive of explicitly generated bytes. Never walks folders or follows links.
public enum OfflineZIPWriter {
 public static func validateZIP32(entryCount:Int,totalBytes:UInt64) throws {
  guard entryCount>0,entryCount<Int(UInt16.max),totalBytes<UInt64(UInt32.max) else { throw OfflineError.invalid("묶음이 ZIP32 한도를 넘어요. 메모를 나누어 내보내 주세요.") }
 }
 private static func validPath(_ path:String) -> Bool {
  let components=path.split(separator:"/",omittingEmptySubsequences:false)
  return !path.isEmpty && !path.hasPrefix("/") && !path.contains("\\") && !path.contains(":")
   && !path.unicodeScalars.contains{$0.value<32 || $0.value==127}
   && components.allSatisfy{!$0.isEmpty && $0 != "." && $0 != ".."}
   && path.utf8.count<Int(UInt16.max)
 }
 private static func append(_ value:UInt64,_ bytes:Int,to data:inout Data) {
  for index in 0..<bytes { data.append(UInt8(truncatingIfNeeded:value >> (index*8))) }
 }
 private static let crcTable:[UInt32]=(0..<256).map { value in
  var c=UInt32(value)
  for _ in 0..<8 { c=(c&1)==1 ? 0xedb88320^(c>>1) : c>>1 }
  return c
 }
 private static func crc32(_ data:Data) throws -> UInt32 {
  var crc=UInt32.max
  for (index,byte) in data.enumerated() {
   if index%65536==0 { try Task.checkCancellation() }
   crc=crcTable[Int((crc ^ UInt32(byte))&255)]^(crc>>8)
  }
  return crc ^ UInt32.max
 }
 public static func archive(entries:[GeneratedEntry]) throws -> Data {
  var canonical=Set<String>(),total:UInt64=22
  for entry in entries {
   guard validPath(entry.path),canonical.insert(entry.path.precomposedStringWithCanonicalMapping).inserted,entry.data.count<Int(UInt32.max) else { throw OfflineError.invalid("안전한 상대 경로의 생성 파일만 묶을 수 있어요.") }
   let amount=UInt64(entry.data.count)+UInt64(entry.path.utf8.count)*2+76
   let sum=total.addingReportingOverflow(amount);guard !sum.overflow else { throw OfflineError.invalid("묶음 크기를 계산하지 못했어요.") };total=sum.partialValue
  }
  try validateZIP32(entryCount:entries.count,totalBytes:total)
  var output=Data(),central=Data();output.reserveCapacity(Int(total))
  for entry in entries {
   try Task.checkCancellation()
   let name=Data(entry.path.utf8),size=UInt64(entry.data.count),crc=UInt64(try crc32(entry.data)),offset=UInt64(output.count)
   append(0x04034b50,4,to:&output);append(20,2,to:&output);append(0x800,2,to:&output);append(0,2,to:&output)
   append(0,2,to:&output);append(33,2,to:&output);append(crc,4,to:&output);append(size,4,to:&output);append(size,4,to:&output)
   append(UInt64(name.count),2,to:&output);append(0,2,to:&output);output.append(name);output.append(entry.data)
   append(0x02014b50,4,to:&central);append(0x0314,2,to:&central);append(20,2,to:&central);append(0x800,2,to:&central);append(0,2,to:&central)
   append(0,2,to:&central);append(33,2,to:&central);append(crc,4,to:&central);append(size,4,to:&central);append(size,4,to:&central)
   append(UInt64(name.count),2,to:&central);append(0,2,to:&central);append(0,2,to:&central);append(0,2,to:&central);append(0,2,to:&central)
   append(UInt64(0o100600)<<16,4,to:&central);append(offset,4,to:&central);central.append(name)
  }
  let offset=UInt64(output.count);output.append(central)
  append(0x06054b50,4,to:&output);append(0,2,to:&output);append(0,2,to:&output);append(UInt64(entries.count),2,to:&output);append(UInt64(entries.count),2,to:&output)
  append(UInt64(central.count),4,to:&output);append(offset,4,to:&output);append(0,2,to:&output)
  guard UInt64(output.count)==total else { throw OfflineError.invalid("묶음 크기 검증에 실패했어요.") }
  return output
 }
}
